from copy import deepcopy

def transform(grid):
    g = deepcopy(grid)
    h, w = len(g), len(g[0])
    # A colored apex with matched down-left/down-right diagonal sides encloses
    # a wedge; fill only its interior with color 2.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0:
                continue
            for d in range(1, h-r):
                left, right = c-d, c+d
                if left < 0 or right >= w:
                    break
                if grid[r+d][left] == color and grid[r+d][right] == color:
                    for x in range(left+1, right):
                        if grid[r+d][x] == 0:
                            g[r+d][x] = 2
                else:
                    break
    return g

demo_in = [[0,0,0,3,0,0,0,0],[0,0,3,0,3,0,0,0],[0,3,0,0,0,3,0,0],[3,0,0,0,0,0,3,0]]
demo_out = [[0,0,0,3,0,0,0,0],[0,0,3,2,3,0,0,0],[0,3,2,2,2,3,0,0],[3,2,2,2,2,2,3,0]]
test = [[0,0,6,0,0,0,0,0,6],[0,6,0,6,0,0,0,6,0],[6,0,0,0,6,0,6,0,0],[0,0,0,0,0,6,0,0,0]]
result = transform(test)
print('demo_match:', transform(demo_in) == demo_out)
print('test_dims:', len(result), len(result[0]))
print('test_output:', result)

