from copy import deepcopy

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = deepcopy(grid)
    # A triangle is outlined by two 45-degree sides meeting at a single
    # marker; fill the interior rows for the maximal contiguous outlined span.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0:
                continue
            for dr in (-1, 1):
                depth = 1
                while 0 <= r + dr*depth < h and c-depth >= 0 and c+depth < w:
                    rr = r + dr*depth
                    if grid[rr][c-depth] != color or grid[rr][c+depth] != color:
                        break
                    for x in range(c-depth+1, c+depth):
                        if grid[rr][x] == 0:
                            out[rr][x] = 2
                    depth += 1
    return out

